const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const start = '2020-01-15';
    const endExcl = '2020-01-22'; // end exclusive => inclusive through 2020-01-21
    const grafton = ee.Geometry.Point([152.934, -29.691]).buffer(10000); // 10 km buffer
    const canberra = ee.Geometry.Point([149.13, -35.28]).buffer(10000); // 10 km buffer

    // Helper to evaluate EE objects
    const evalEE = (obj) =>
      new Promise((resolve, reject) => obj.evaluate((res, err) => err ? reject(err) : resolve(res)));

    // 2. Data Acquisition & Check with fallback
    let dataset = 'CHIRPS';
    let bandName = 'precip';
    let scale = 5000;

    let col = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(start, endExcl)
      .select('precipitation');

    let nImages = await evalEE(col.size());
    if (!nImages || nImages === 0) {
      // Fallback to ERA5-LAND DAILY aggregated
      dataset = 'ERA5_LAND_DAILY';
      scale = 9000;
      col = ee.ImageCollection('ECMWF/ERA5_LAND/DAILY_AGGR')
        .filterDate(start, endExcl)
        .select('total_precipitation_sum');
      nImages = await evalEE(col.size());
      if (!nImages || nImages === 0) {
        console.log(`Period: 2020-01-15 to 2020-01-21`);
        console.log(`Dataset: None available`);
        console.log(`Images: 0`);
        console.log('C1');
        return;
      }
    }

    // 3. Processing: sum precipitation over the period, convert to mm, and compute stats
    let sumImg;
    if (dataset === 'CHIRPS') {
      // CHIRPS precipitation is in mm/day
      sumImg = col.sum().rename(bandName); // total mm over the period
    } else {
      // ERA5 total_precipitation_sum is meters/day; convert to mm and sum
      sumImg = col.sum().multiply(1000).rename(bandName); // total mm
    }

    const reducer = ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true});
    const statsG = await evalEE(sumImg.reduceRegion({
      reducer: reducer,
      geometry: grafton,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));
    const statsC = await evalEE(sumImg.reduceRegion({
      reducer: reducer,
      geometry: canberra,
      scale: scale,
      maxPixels: 1e9,
      bestEffort: true
    }));

    const meanG = statsG ? statsG[`${bandName}_mean`] : null;
    const countG = statsG ? statsG[`${bandName}_count`] : 0;
    const meanC = statsC ? statsC[`${bandName}_mean`] : null;
    const countC = statsC ? statsC[`${bandName}_count`] : 0;

    // 4. Validation for C2/C3
    if ((countG === 0) || (countC === 0)) {
      console.log(`Period: 2020-01-15 to 2020-01-21`);
      console.log(`Dataset: ${dataset}, Images: ${nImages}`);
      console.log(`Grafton pixels: ${countG}, Canberra pixels: ${countC}`);
      console.log('C2');
      return;
    }
    const invalid = (v) => v === null || Number.isNaN(v) || !isFinite(v) || v < 0 || v > 2000; // sanity range for 7-day total (mm)
    if (invalid(meanG) || invalid(meanC)) {
      console.log(`Period: 2020-01-15 to 2020-01-21`);
      console.log(`Dataset: ${dataset}, Images: ${nImages}`);
      console.log(`Invalid values -> Grafton: ${meanG}, Canberra: ${meanC}`);
      console.log('C3');
      return;
    }

    // 5. Final calculation and answer
    const diff = meanG - meanC; // mm
    console.log(`Period: 2020-01-15 to 2020-01-21`);
    console.log(`Dataset: ${dataset}, Images: ${nImages}, Scale(m): ${scale}`);
    console.log(`Grafton total(mm, 10km mean): ${meanG.toFixed(1)}, pixels: ${countG}`);
    console.log(`Canberra total(mm, 10km mean): ${meanC.toFixed(1)}, pixels: ${countC}`);
    console.log(`Difference (Grafton - Canberra): ${diff.toFixed(1)} mm`);
    if (diff > 0) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${String(err).slice(0, 120)}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
